from collections import deque
comp={}; cid=0
for r in range(29):
 for c in range(12):
  if G[r][c]==4 and (r,c) not in comp:
   cid+=1; comp[(r,c)]=cid; q=deque([(r,c)])
   while q:
    x,y=q.popleft()
    for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=p[0]<29 and 0<=p[1]<12 and G[p[0]][p[1]]==4 and p not in comp:
      comp[p]=cid;q.append(p)
